import itertools

def solve_game(n):
    cards = list(range(1, n + 1))

    def get_winner_score(current_cards, s1, s2, turn_idx):
        # turn_idx: 0 for Grogg, 1 for Winnie
        # turn_idx is also the number of cards already placed
        if not current_cards:
            return abs(s1 - s2)

        player = "Grogg" if turn_idx % 2 == 0 else "Winnie"

        results = []
        for card in current_cards:
            # Player chooses card and pile
            # Pile 1
            res1 = get_winner_score([c for c in current_cards if c != card], s1 + card, s2, turn_idx + 1)
            # Pile 2
            res2 = get_winner_score([c for c in current_cards if c != card], s1, s2 + card, turn_idx + 1)

            # The player chooses the card and the pile. 
            # Wait, the player chooses the card AND then chooses the pile.
            # This means for a given card, they will choose the pile that's best for them.
            # Then they will choose the card that's best for them.

            # If Winnie's turn: she chooses card and pile to maximize.
            # If Grogg's turn: he chooses card and pile to minimize.

            # Let's refine:
            # For a chosen card, the player will pick the pile that helps their goal.
            if player == "Winnie":
                best_pile_score = max(res1, res2)
            else:
                best_pile_score = min(res1, res2)
            results.append(best_pile_score)

        if player == "Winnie":
            return max(results)
        else:
            return min(results)

    return get_winner_score(cards, 0, 0, 0)

for n in range(1, 9):
    print(f"n={n}, result={solve_game(n)}")

